begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(8);
select ok(public.valid_companion_selection('{"mode":"mixed","characterSlugs":["male-01","moss-fox","realistic-01"]}'),'Mixed styles are accepted');
select ok(not public.valid_companion_selection('{"mode":"characters","characterSlugs":["famous-unlicensed"]}'),'Unknown characters remain rejected');
select ok(public.valid_companion_selection('{"mode":"characters","characterSlugs":["male-01","male-02","male-03","male-04","female-01","female-02","female-03","female-04","moss-fox"]}'),'Selections can exceed eight for pagination');
select ok(public.valid_companion_selection('{"mode":"characters","characterSlugs":["realistic-01","realistic-02","realistic-03","realistic-04","realistic-05","realistic-06","realistic-07","realistic-08"]}'),'All eight realistic partners are accepted');
select ok(public.valid_companion_selection('{"mode":"mixed","characterSlugs":["realistic-08","pip-owl","female-02"]}'),'New realistic partners mix with existing styles');
select ok(not public.valid_companion_selection('{"mode":"characters","characterSlugs":["realistic-13"]}'),'Unknown realistic partner is rejected');
select ok(public.valid_companion_selection('{"mode":"mixed","characterSlugs":["realistic-09","realistic-10","realistic-11","realistic-12","moss-fox"]}'),'Expanded GIF cast mixes with existing partners');
select ok(public.valid_companion_selection(jsonb_build_object('mode','characters','characterSlugs',jsonb_build_array('male-01','male-02','male-03','male-04','female-01','female-02','female-03','female-04','moss-fox','pip-owl','momo-cloud','realistic-01','realistic-02','realistic-03','realistic-04','realistic-05','realistic-06','realistic-07','realistic-08','realistic-09','realistic-10','realistic-11','realistic-12'))),'The complete known cast is accepted');
select * from finish();
rollback;
